    const a = w.vert(CLIFF_X + 3, LAKE_Y, -900, 0, 1, 0), c = w.vert(1200, LAKE_Y, -900, 0, 1, 0), d = w.vert(1200, LAKE_Y, 900, 0, 1, 0), e = w.vert(CLIFF_X + 3, LAKE_Y, 900, 0, 1, 0);
    w.quad(a, e, d, c);
